select users.display_name, (select count(*)::text from logs) as logs, (select count(*)::text from contest_logs) as contest_logs, (select count(*)::text from log_tags) as tags, (select count(*)::text from leaderboard_outbox) as outbox, (select count(*)::text from jobs) as jobs from users where id='11111111-1111-4111-8111-111111111111';
